function jk(){const n=new Date(Date.now()+7*3600e3);return{d:n.getUTCDay(),m:n.getUTCHours()*60+n.getUTCMinutes()}}
function hoursBox(){const t=jk();let open=false;const rows=HRS.map(h=>{const today=h[2].includes(t.d);if(today&&h[3]&&t.m>=h[3][0]&&t.m<h[3][1])open=true;return`<div${today?' class="today"':''}><span>${h[0]}</span><span>${h[1]}</span></div>`}).join('');
return`<div class="opn${open?' y':''}"><i></i><span>${open?'Open now':'Closed now'}</span></div><div class="hours">${rows}</div><p class="fn">Times shown in Jakarta time (WIB).</p>`}
