lb.addEventListener('click',e=>{const b=e.target.closest('button');if(b){b.classList.contains('p')?show(li-1):b.classList.contains('n')?show(li+1):lb.classList.remove('o')}else if(e.target==lb)lb.classList.remove('o')});
