const RV=[['Sarah Whitmore','Sydney, Australia','2BR Penthouse · 6 months',27,'We relocated for work and Simprug Park felt like home within the first week. The penthouse terrace is wonderful in the evening, and the team sorts everything out before we even ask.','Kami pindah karena pekerjaan dan Simprug Park terasa seperti rumah sejak minggu pertama. Teras penthouse-nya indah di malam hari, dan tim menyelesaikan segalanya sebelum kami meminta.'],
['Hiroshi Tanaka','Tokyo, Japan','Typical 2BR · 1 year',25,'Quiet, clean and perfectly placed for Senayan. The dining and living space is generous enough for our whole family, and housekeeping is always on time.','Tenang, bersih, dan lokasinya pas dekat Senayan. Ruang makan dan ruang tamunya cukup luas untuk seluruh keluarga, dan layanan kebersihan selalu tepat waktu.'],
['Rina Kusuma','Jakarta, Indonesia','Type C · 8 months',24,'The spacious living area and the study corner were exactly what I needed for working from home. My children love the pool and the playground downstairs.','Ruang tamu yang lapang dan sudut belajar persis seperti yang saya butuhkan untuk bekerja dari rumah. Anak-anak saya suka kolam dan taman bermain di bawah.'],
['Daniel Meier','Munich, Germany','Type A & B · 2 years',26,'Thoughtful finishes, custom furniture and genuinely attentive staff. After two years, extending our stay was the easiest decision we made.','Finishing yang matang, furnitur custom, dan staf yang benar-benar perhatian. Setelah dua tahun, memperpanjang masa tinggal adalah keputusan termudah kami.'],
['Amelia Santoso','Bandung, Indonesia','2BR Penthouse · 4 months',28,'A calm, green corner of South Jakarta with a hotel-like level of service. The garden pool is perfect for slow weekends with the kids.','Sudut Jakarta Selatan yang tenang dan hijau dengan layanan selevel hotel. Kolam taman sangat pas untuk akhir pekan santai bersama anak-anak.'],
['James & Priya Nair','Singapore','Typical 2BR · 10 months',13,'The sky terrace evenings became our favourite ritual. Well-maintained, quiet and close to everything we need. Highly recommended for families.','Malam di teras langit menjadi ritual favorit kami. Terawat, tenang, dan dekat dengan semua yang kami butuhkan. Sangat direkomendasikan untuk keluarga.']];
const star='<svg class="f" viewBox="0 0 24 24"><path d="M12 2.5l2.9 6.1 6.6.8-4.9 4.6 1.3 6.6L12 17.3 6.1 20.6l1.3-6.6L2.5 9.4l6.6-.8z"/></svg>';
const stars=star.repeat(5);
const av=(n,i)=>{const h=[28,200,150,340,18,260][i%6],t=n.split(/[ &]+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('');return 'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="hsl(${h},38%,62%)"/><stop offset="1" stop-color="hsl(${h},42%,34%)"/></linearGradient></defs><circle cx="32" cy="32" r="32" fill="url(#g)"/><text x="32" y="40" text-anchor="middle" font-family="Georgia,serif" font-size="24" fill="#fff">${t}</text></svg>`)};
function buildRV(){const c=r=>r.map((x,i)=>`<button class="rc2" data-r="${i}" aria-label="${x[0]}"><div class="stars" aria-label="5 stars">${stars}</div><p>${LG=='id'?x[5]:x[4]}</p><div class="who"><img src="${av(x[0],i)}" alt=""><div><b>${x[0]}</b><span>${x[1]}</span></div></div></button>`).join('');
$('#tk').innerHTML=c(RV)+c(RV).replace(/data-r/g,'tabindex="-1" aria-hidden="true" data-r')}
const rm=$('#rm');function openRV(i){const x=RV[i];rm.querySelector('.ri').style.backgroundImage=`url(${I[x[3]]})`;rm.querySelector('.rt').innerHTML=`<div class="who"><img src="${av(x[0],i)}" alt=""><div><b>${x[0]}</b><span>${x[1]}</span></div></div><div class="stars" style="font-size:20px">${stars}</div><p>${LG=='id'?x[5]:x[4]}</p><small>${x[2]}</small>`;rm.classList.add('o')}
$('#tk').addEventListener('click',e=>{const b=e.target.closest('.rc2');if(b)openRV(+b.dataset.r)});
rm.addEventListener('click',e=>{if(e.target==rm||e.target.closest('.rx'))rm.classList.remove('o')});
/* language */
const lgE=$('#lg');function setLang(l,s){LG=l;try{localStorage.setItem('sp-lang',l)}catch(e){}document.documentElement.lang=l;lgE.querySelectorAll('li button').forEach(b=>b.setAttribute('aria-selected',b.dataset.l==l));$('#lgc').textContent=l.toUpperCase();$('#lgf').innerHTML=lgE.querySelector(`[data-l=${l}] .fl`).innerHTML;tr(document.body);buildRV();if(!s&&rm.classList.contains('o'))rm.classList.remove('o')}
$('#lgb').onclick=e=>{e.stopPropagation();const o=lgE.classList.toggle('o');$('#lgb').setAttribute('aria-expanded',o)};
lgE.querySelectorAll('li button').forEach(b=>b.onclick=()=>{setLang(b.dataset.l);lgE.classList.remove('o')});
/* emergency */
const emp=$('#emp'),emb=$('#em');const setEmp=o=>{emp.classList.toggle('o',o);emp.setAttribute('aria-hidden',!o);emb.setAttribute('aria-expanded',o)};
emb.onclick=e=>{e.stopPropagation();setEmp(!emp.classList.contains('o'))};$('#emx').onclick=()=>setEmp(false);
$('#cp').onclick=e=>copyBtn(e.currentTarget,e.currentTarget.dataset.n,'Copied');
document.addEventListener('click',e=>{if(!e.target.closest('#lg'))lgE.classList.remove('o');if(!e.target.closest('#emp'))setEmp(false)});
document.addEventListener('keydown',e=>{if(e.key=='Escape'){lgE.classList.remove('o');setEmp(false);rm.classList.remove('o')}});
/* effects */
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){const t=e.target;t.classList.add('in');io.unobserve(t);setTimeout(()=>{t.classList.remove('rv','in');t.style.transitionDelay=''},1500)}}),{threshold:.1,rootMargin:'0px 0px -5% 0px'});
function enh(){tr($('#app'));document.querySelectorAll('#app .hd,#app .card,#app .split>*,#app .am div,#app .hl>div,#app .mas button,#app .band .wrap,#app .gal,#app .det>*').forEach((e,i)=>{e.classList.add('rv');e.style.transitionDelay=(i%4)*.09+'s';io.observe(e)})}
addEventListener('scroll',()=>{const y=scrollY,m=document.documentElement.scrollHeight-innerHeight;$('#pr').style.transform=`scaleX(${m>0?y/m:0})`;const t=document.querySelector('.hero .tx');if(t&&y<900){t.style.transform=`translateY(${y*.18}px)`;t.style.opacity=Math.max(0,1-y/650)}},{passive:true});
setLang(LG,1);

/* router */
function route(){const h=(location.hash||'#home').slice(1);let k=h.startsWith('room-')?'room':h.startsWith('update-')?'update':h in P?h:'home';const a=$('#app');clearInterval(tm);
a.className='pgv';a.innerHTML=k=='room'?room(h.slice(5)):k=='update'?updatePage(h.slice(7)):P[k]();a.querySelectorAll('[data-img]').forEach(e=>e.src=I[e.dataset.img]);
document.querySelectorAll('nav.d a.l').forEach(x=>x.classList.toggle('on',x.getAttribute('href')=='#'+(k=='room'?'rooms':k=='update'?'updates':k)));
if(k=='home')initHero();if(k=='room')initRoom(h.slice(5));
a.querySelectorAll('[data-lb]').forEach((b,i,all)=>b.onclick=()=>openLB([...all].map(x=>x.dataset.lb),i));
initPages();
dr(0);window.scrollTo(0,0);document.title=(k=='home'?'Simprug Park Residences':k=='update'?(UP.find(x=>x.id==h.slice(7))||UP[0]).title+' — Simprug Park':k=='room'?R.find(x=>x.id==h.slice(5))?.n+' — Simprug Park':k[0].toUpperCase()+k.slice(1)+' — Simprug Park')}
document.querySelectorAll('[data-img]').forEach(e=>e.src=I[e.dataset.img]);
const _route=route;route=function(){_route();enh()};addEventListener('hashchange',route);route();
addEventListener('scroll',()=>$('#hd').classList.toggle('s',scrollY>60),{passive:true});
/* drawer + theme */
function dr(o){$('#dr').classList.toggle('o',!!o)}$('#bg').onclick=()=>dr(1);$('#bk').onclick=$('#dx').onclick=()=>dr(0);$('#dr').addEventListener('click',e=>{if(e.target.closest('.mn a'))dr(0)});
const sun='<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5L19 19M5 19l1.5-1.5M17.5 6.5L19 5"/></svg>',moon='<svg viewBox="0 0 24 24"><path d="M20 14.5A8 8 0 019.5 4 8 8 0 1020 14.5z"/></svg>';
const dark=()=>document.documentElement.dataset.theme?document.documentElement.dataset.theme=='dark':matchMedia('(prefers-color-scheme:dark)').matches;
function sync(){const d=dark();document.documentElement.dataset.theme=d?'dark':'light';$('#th').innerHTML='<span class="kn">'+(d?moon:sun)+'</span>';$('#th').setAttribute('aria-pressed',d)}
try{const t=localStorage.getItem('sp-theme');if(t)document.documentElement.dataset.theme=t}catch(e){}
$('#th').onclick=()=>{const t=dark()?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('sp-theme',t)}catch(e){}sync()};sync();
